import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def run_cmd(args, expect=0):
    proc = subprocess.run(args, cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect, (args, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload.get('items', [])]

thread_root = write_project('stdlib_thread_surface', '''
    use core.thread;

    fn worker() -> i32 {
        discard thread.checkpoint_now()
        return 0
    }

    fn tagged_worker() -> i32 {
        return thread.context_id()
    }

    fn main() -> i32 {
        let current = thread.current_context()
        if current.bound != 0 {
            return 11
        }
        if thread.context_id_or(9) != 9 {
            return 12
        }

        discard thread.timeout_after(5000)
        discard thread.deadline_after(5000)

        let group = thread.group_begin()
        discard thread.group_spawn_n(group, worker, 2)
        let grouped = thread.group_join_all(group)
        if grouped != 0 {
            return 13
        }

        let tagged = thread.spawn_task_in_context(tagged_worker, 41)
        let tagged_result = thread.join_task(tagged)
        if tagged_result != 41 {
            return 14
        }
        return 0
    }
''')

legacy_root = write_project('stdlib_concurrency_private', '''
    use core.concurrency;

    fn main() -> i32 {
        let policy = concurrency.drop_oldest_policy_with_high_watermark(4, 3)
        let state = concurrency.snapshot(3, policy)
        return concurrency.depth_after_recv(state)
    }
''')

host_root = write_project('stdlib_thread_surface_host', '''
    use core.thread;

    fn worker() -> i32 {
        discard thread.checkpoint_now()
        return 0
    }

    fn tagged_worker() -> i32 {
        return thread.context_id()
    }

    fn main() -> i32 {
        let tagged = thread.spawn_task_in_context(tagged_worker, 41)
        if thread.join_task(tagged) != 41 {
            return 11
        }
        let group = thread.group_begin()
        discard thread.group_spawn_n(group, worker, 2)
        if thread.group_join_all(group) != 0 {
            return 12
        }
        return 0
    }
''')

build_payload = run_cmd([str(fz), 'build', str(thread_root), '--json'])
assert build_payload['status'] == 'ok', build_payload
verify_payload = run_cmd([str(fz), 'verify', str(thread_root), '--json'])
assert verify_payload['errors'] == 0, verify_payload
run_payload = run_cmd([str(fz), 'run', str(thread_root), '--det', '--json'])
assert run_payload['status'] == 'pass', run_payload
legacy_verify = run_cmd([str(fz), 'verify', str(legacy_root), '--json'], expect=1)
assert legacy_verify['errors'] > 0, legacy_verify
assert any('module `concurrency`' in message or 'core.concurrency' in message for message in messages(legacy_verify)), legacy_verify
host_payload = run_cmd([str(fz), 'run', str(host_root), '--proc-backend', 'host', '--fs-backend', 'host', '--http-backend', 'host', '--json'])
assert host_payload['status'] == 'ok' and host_payload['exitCode'] == 0, host_payload
print('compiler-stdlib-thread-surface-ok')
